import {managerDecisionPending,stayManager} from './career.js';
import {ROLES,SKILLS} from './data.js';
import {overall,getPlayer,starters,squad,academy,rng,clamp,createPlayer,mean,composition,decayConnections,draftEligible} from './engine.js';
export const SQUAD_ROLES=['Starter','Rotation','Prospect'];
export const PRIORITIES=['Playing time','Winning','Security','Salary'];
export const CONTRACT_YEARS=[1,2,3,4,5];
export function preferredContractYears(p){if(CONTRACT_YEARS.includes(p.preferredYears))return p.preferredYears;const variation=Math.floor((Number(p.id.slice(1))||0)/4);return p.preference==='Security'?4+variation%2:p.preference==='Salary'?1+variation%2:p.age>=29?1+variation%2:p.preference==='Winning'?2+variation%3:1+variation%3;}
const round=n=>Math.round(n/500)*500;
const ok=message=>({ok:true,message});
const no=message=>({ok:false,message});
export function ensureMarket(s){
 s.market??={clock:0,window:null,offers:[],inbox:[],ledger:[],shortlist:[],next:1};
 for(const t of s.teams){t.funds??=280000+t.id%5*25000;t.wageLimit??=360000;t.reputation??=50;}
 for(const p of s.players){p.academyService??=p.team===s.team&&p.squad==='academy'?p.trainingWeeks:0;p.developmentPaid??=false;p.preference??=PRIORITIES[(Number(p.id.slice(1))||0)%4];p.preferredYears??=preferredContractYears(p);p.homeRegion??=p.team>=0?s.teams[p.team].region:(Number(p.id.slice(1))%2?'LCS':'LCK');p.trust??=70;p.listing??='Available';if(p.contract){p.contract.role??=p.squad==='academy'?'Prospect':s.teams[p.team]?.lineup[p.role]===p.id?'Starter':'Rotation';}}
 if(s.phase==='offseason'&&s.market.window?.year!==s.year+1)beginOffseason(s);
 if(s.phase==='offseason'&&s.market.window){s.market.window.developmentBaseline??={};for(const p of s.players)if(!s.market.window.developmentBaseline[p.id])s.market.window.developmentBaseline[p.id]={skills:{...p.skills},team:p.team,form:p.form,traits:[...p.traits]};}
 return s.market;
}
export const targetYear=s=>s.phase==='offseason'?s.year+1:s.year;
export const regularSeriesPlayed=(s,t=s.team)=>s.results.filter(r=>r.year===s.year&&r.split===s.split&&r.phase==='regular'&&(r.a===t||r.b===t)).length;
export const marketOpen=s=>!s.match&&(s.phase==='draft'||s.phase==='regular'&&regularSeriesPlayed(s)<5||s.phase==='offseason'&&s.market.window?.stage==='open');
export const cashFor=(s,t=s.team)=>t===s.team?s.budget:s.teams[t].funds;
function money(s,t,delta){if(t===s.team)s.budget=Math.round(s.budget+delta);else s.teams[t].funds=Math.round(s.teams[t].funds+delta);}
export const payroll=(s,t=s.team)=>s.players.filter(p=>p.team===t).reduce((n,p)=>n+(p.contract?.salary||0),0);
const pending=o=>['waiting','counter','agreed'].includes(o.status);
export const heldCash=s=>s.market.offers.filter(pending).reduce((n,o)=>n+o.bonus,0);
export const spendable=s=>Math.max(0,s.budget-heldCash(s));
export function committedPayroll(s){return payroll(s)+s.market.offers.filter(pending).reduce((n,o)=>n+Math.max(0,o.salary-(getPlayer(s,o.player)?.team===s.team?getPlayer(s,o.player).contract.salary:0)),0);}
export function askingTerms(s,p,t=s.team){const o=overall(p),starter=getPlayer(s,s.teams[t].lineup[p.role]);const role=p.squad==='academy'&&p.team===t?'Prospect':o>=(starter?overall(starter)-3:72)?'Starter':'Rotation';const salary=round(Math.max(role==='Prospect'?9000:15000,(o-50)*950)*(p.preference==='Salary'?1.12:1)*(1+(70-p.trust)*.003));return {salary,bonus:round(salary*.22),years:preferredContractYears(p),role};}
export function marketValue(s,p){const years=Math.max(1,(p.contract?.end||s.year)-targetYear(s)+1);return round(Math.max(5000,(overall(p)-52)*1800+(p.age<23?(23-p.age)*2200:0)+p.growth*180)*(1+Math.min(3,years)*.16));}
function log(s,type,text,players=[],amount=0){s.market.ledger.unshift({id:'l'+s.market.next++,year:s.year,day:s.market.clock,type,text,players,amount});s.market.ledger=s.market.ledger.slice(0,400);s.news.unshift(text);s.news=s.news.slice(0,30);}
function full(s,t){return squad(s,t).length>=7;}
export function rosterRoom(s,t,group,id){return s.players.filter(p=>p.team===t&&p.squad===group&&p.id!==id).length<(group==='academy'?6:7);}
function tradeFits(s,t,outgoing,incoming){const ps=[...s.players.filter(p=>p.team===t&&!outgoing.includes(p.id)),...incoming.map(id=>getPlayer(s,id))];const main=ps.filter(p=>p.squad==='main');let promotions=0;for(const role of ROLES)if(!main.some(p=>p.role===role)&&ps.some(p=>p.role===role))promotions++;return main.length+promotions<=7&&ps.length-main.length-promotions<=6;}
function fillRole(s,t,role){const current=getPlayer(s,s.teams[t].lineup[role]);if(current?.team===t&&current.squad==='main')return;let p=s.players.filter(p=>p.team===t&&p.role===role).sort((a,b)=>(b.squad==='main')-(a.squad==='main')||overall(b)-overall(a))[0];if(!p){p=createPlayer(s,role,35+rng(s)*8,t,'main');p.emergency=true;p.contract={salary:12000,end:targetYear(s),role:'Rotation'};s.players.push(p);log(s,'Reserve',`${s.teams[t].tag} register reserve ${p.name} at ${role}.`,[p.id]);}p.squad='main';s.teams[t].lineup[role]=p.id;}
function cancelFor(s,id,except){for(const o of s.market.offers)if(o.player===id&&o.id!==except&&pending(o)){o.status='unavailable';o.message='The player is no longer available on these terms.';}}
export function beginOffseason(s){if(s.market.window?.year===s.year+1)return;s.market.window={year:s.year+1,stage:'review',day:0,total:6,camp:null,grant:0,developmentBaseline:Object.fromEntries(s.players.map(p=>[p.id,{skills:{...p.skills},team:p.team,form:p.form,traits:[...p.traits]}])),startRating:mean(starters(s).map(overall)),startRoster:starters(s).map(p=>({id:p.id,name:p.name,role:p.role,ovr:overall(p)}))};for(const t of s.teams){const wins=s.results.filter(r=>r.year===s.year&&r.winner===t.id).length;t.reputation=clamp(40+wins*2,30,95);t.wageLimit=Math.max(t.wageLimit,round(310000+wins*3500),payroll(s,t.id));}log(s,'Window',`The ${s.year+1} offseason begins. Review expiring contracts before opening free agency.`);}
export function toggleShortlist(s,id){if(!getPlayer(s,id))return false;const a=s.market.shortlist,i=a.indexOf(id);if(i<0)a.push(id);else a.splice(i,1);return true;}
export function setListing(s,id,value){const p=getPlayer(s,id);if(s.match||p?.team!==s.team||!['Available','Listed','Untouchable'].includes(value))return no('This player cannot be listed now.');p.listing=value;return ok(value==='Listed'?'Clubs will consider offers for this player.':'Transfer status updated.');}
export function offerEvaluation(s,p,terms,t=s.team){const ask=askingTerms(s,p,t);const reasons=[];let score=55+(terms.salary/ask.salary-1)*75+(terms.bonus/Math.max(500,ask.bonus)-1)*10;const roleValue={Starter:12,Rotation:0,Prospect:-14};score+=roleValue[terms.role]-roleValue[ask.role];if(p.preference==='Playing time')score+=(roleValue[terms.role]-roleValue[ask.role])*.6;const lengthGap=terms.years-ask.years;score-=Math.abs(lengthGap)*(p.preference==='Security'&&lengthGap<0?9:lengthGap>0?7:5);if(p.preference==='Winning')score+=(s.teams[t].reputation-50)*.35;if(p.homeRegion===s.teams[t].region)score+=3;if(p.team===t)score+=5+(p.trust-70)*.2;if(terms.salary<ask.salary)reasons.push('Salary is below the agent’s target.');if(roleValue[terms.role]<roleValue[ask.role])reasons.push('The proposed role is smaller than the player wants.');if(lengthGap)reasons.push(`Prefers ${ask.years} year${ask.years>1?'s':''}; this offer is ${lengthGap>0?'longer':'shorter'} than requested.`);if(p.preference==='Winning'&&s.teams[t].reputation<55)reasons.push('The player is attracted to title contenders.');const incumbent=getPlayer(s,s.teams[t].lineup[p.role]);if(terms.role==='Starter'&&incumbent?.id!==p.id)reasons.push(`You must make room at ${p.role} to honor a starting promise.`);return {score:clamp(score,0,100),label:score>=70?'Very interested':score>=55?'Open to the deal':score>=40?'Needs convincing':'Unlikely',reasons,ask};}
function validTerms(v){return v&&Number.isInteger(v.salary)&&v.salary>=5000&&v.salary<=200000&&Number.isInteger(v.bonus)&&v.bonus>=0&&v.bonus<=500000&&CONTRACT_YEARS.includes(v.years)&&SQUAD_ROLES.includes(v.role);}
export function submitOffer(s,id,terms){ensureMarket(s);const p=getPlayer(s,id);if(s.match||!p||!validTerms(terms))return no('Enter valid salary, bonus, length (1–5 years) and role.');if(p.team!==s.team&&!draftEligible(s,p,s.team))return no('This special player only signs for LCS or LCK clubs.');if(s.phase==='offseason'&&s.market.window.stage==='closed')return no('The transfer deadline has passed. Continue to preseason.');if(s.phase==='draft'&&s.draft.pool.includes(id)&&p.team<0&&!s.draft.complete)return no('This prospect must go through the academy draft.');if(p.team!==-1&&p.team!==s.team)return no('Agree a transfer with the player’s club first.');if(s.phase==='offseason'&&s.market.window.stage==='review'&&p.team!==s.team)return no('Free agency opens after contract review.');if(!rosterRoom(s,s.team,terms.role==='Prospect'&&s.teams[s.team].lineup[p.role]!==p.id?'academy':'main',p.id))return no('Roster full: at most 2 bench players and 6 academy players. Move, release or trade a player first.');if(s.phase==='offseason'&&s.market.window.stage==='open'&&s.market.window.day>=6)return no('Deadline reached. New contract bids are closed; finish agreed deals.');const old=s.market.offers.find(o=>o.player===id&&pending(o));if(old?.status==='waiting')return no('Wait for the agent’s response or withdraw the existing offer.');const cash=s.budget-heldCash(s)+(old?.bonus||0),wages=committedPayroll(s)-(old?Math.max(0,old.salary-(p.team===s.team?p.contract.salary:0)):0)+Math.max(0,terms.salary-(p.team===s.team?p.contract.salary:0));if(terms.bonus>cash)return no('Insufficient uncommitted cash for the signing bonus.');if(wages>s.teams[s.team].wageLimit)return no('This offer exceeds the annual wage budget.');if(old)old.status='replaced';const o={id:'o'+s.market.next++,player:id,from:p.team,renewal:p.team===s.team,...terms,status:'waiting',created:s.market.clock,expires:s.market.clock+3,round:(old?.round||0)+1,rivals:old?.rivals||[],message:'The agent will reply on the next market advance.'};s.market.offers.push(o);if(p.team<0&&!o.rivals.length){const interested=s.teams.filter(t=>t.id!==s.team&&draftEligible(s,p,t.id)&&!full(s,t.id)&&payroll(s,t.id)+terms.salary<t.wageLimit).sort((a,b)=>{const pa=getPlayer(s,a.lineup[p.role]),pb=getPlayer(s,b.lineup[p.role]);return overall(pa)-overall(pb);}).slice(0,2);for(const t of interested)if(rng(s)<.7){const ask=askingTerms(s,p,t.id);o.rivals.push({team:t.id,salary:round(ask.salary*(.92+rng(s)*.2)),bonus:ask.bonus,years:ask.years,role:ask.role});}}return ok('Offer sent. The bonus and wage space are reserved until a decision.');}
export function withdrawOffer(s,id){const o=s.market.offers.find(x=>x.id===id);if(s.match||!o||!pending(o))return no('Offer is no longer active.');o.status='withdrawn';o.message='You withdrew this offer.';return ok('Offer withdrawn. Reserved funds released.');}
function contractEnd(s,o,p){return o.renewal?Math.max(p.contract.end,s.year)+o.years:targetYear(s)+o.years-1;}
function signContract(s,o,t=s.team){const p=getPlayer(s,o.player);if(!p||!o.renewal&&!draftEligible(s,p,t)||(o.renewal?p.team!==t:p.team!==-1)||!rosterRoom(s,t,o.role==='Prospect'&&s.teams[t].lineup[p.role]!==p.id?'academy':'main',p.id))return false;const oldSalary=p.team===t?p.contract.salary:0;if(cashFor(s,t)<o.bonus||t===s.team&&spendable(s)+(pending(o)?o.bonus:0)<o.bonus||payroll(s,t)-oldSalary+o.salary>s.teams[t].wageLimit)return false;const end=contractEnd(s,o,p);money(s,t,-o.bonus);if(!o.renewal)p.academyService=0;p.team=t;p.squad=o.role==='Prospect'?'academy':'main';p.contract={salary:o.salary,end,role:o.role,promise:{played:0,eligible:0,checked:0}};p.listing='Available';p.emergency=false;p.trust=clamp(p.trust+3,0,100);if(o.renewal&&s.teams[t].lineup[p.role]===p.id)p.squad='main';cancelFor(s,p.id,o.id);log(s,o.renewal?'Renewal':'Signing',`${s.teams[t].tag} ${o.renewal?'extend':'sign'} ${p.name}: $${o.salary.toLocaleString()}/year through ${end}.`,[p.id],o.bonus);return true;}
export function acceptOffer(s,id){const o=s.market.offers.find(x=>x.id===id);if(s.match||!o||o.status!=='agreed')return no('Wait for agreed terms from the agent.');if(s.market.clock>o.expires)return no('The agreement has expired.');if(!signContract(s,o))return no('The deal no longer fits your roster or finances.');o.status='signed';o.message='Contract signed.';return ok('Signed. Review the lineup to honor the agreed playing role.');}
export function processOffers(s){for(const o of s.market.offers.filter(pending)){const p=getPlayer(s,o.player);if(!p||p.team!==o.from){o.status='unavailable';continue;}if(o.status!=='waiting'){if(s.market.clock>o.expires){o.status='expired';o.message='The agent’s deadline passed.';}continue;}const evaluation=offerEvaluation(s,p,o);const rivals=o.rivals.filter(r=>draftEligible(s,p,r.team)&&cashFor(s,r.team)>=r.bonus&&payroll(s,r.team)+r.salary<=s.teams[r.team].wageLimit&&!full(s,r.team));const rival=rivals.sort((a,b)=>offerEvaluation(s,p,b,b.team).score-offerEvaluation(s,p,a,a.team).score)[0];const rivalScore=rival?offerEvaluation(s,p,rival,rival.team).score:0;if(rival&&rivalScore>evaluation.score+8&&rivalScore>=55&&signContract(s,{...rival,player:p.id,renewal:false,id:o.id},rival.team)){o.status='lost';o.message=`Signed with ${s.teams[rival.team].name}. Their offer better matched the player’s priorities.`;continue;}if(evaluation.score>=55){o.status='agreed';o.expires=s.market.clock+2;o.message='The player chose your offer. Sign within two market advances.';}else if(o.round<3&&rng(s)<.65){o.status='counter';o.expires=s.market.clock+2;o.counter={...evaluation.ask,salary:Math.max(evaluation.ask.salary,o.salary),bonus:Math.max(evaluation.ask.bonus,o.bonus)};const counterScore=offerEvaluation(s,p,o.counter).score;if(counterScore<60)o.counter.salary=Math.min(200000,o.counter.salary+Math.ceil((60-counterScore)*evaluation.ask.salary/75/500)*500);o.message=`The agent countered with ${o.counter.years} year${o.counter.years>1?'s':''}, the player’s preferred length. Review the salary, bonus and role.`;}else{o.status='rejected';o.message=o.round>=3?'Negotiations ended after three unsuccessful offers.':'The player declined the package rather than making a counteroffer.';}}}
export function reviewResponses(s){if(s.match||s.phase==='offseason'&&s.market.window.stage!=='review'||s.phase!=='offseason'&&s.phase!=='draft')return no('Responses arrive with the next matchday or transfer round.');s.market.clock++;processOffers(s);return ok('Agents have responded. Check Negotiations.');}
export function openWindow(s){ensureMarket(s);if(managerDecisionPending(s))return no('Choose your next manager position in Career before opening free agency.');const w=s.market.window;if(s.phase!=='offseason'||w.stage!=='review'||s.match||s.clubEvent||s.celebration)return no('Finish pending club decisions before opening the window.');if(s.market.offers.some(o=>pending(o)&&o.renewal))return no('Sign or withdraw your pending renewals first.');for(const p of s.players.filter(p=>p.team>=0&&p.contract.end===s.year)){if(p.team!==s.team&&rng(s)<.65&&!p.emergency){const terms=askingTerms(s,p,p.team);if(payroll(s,p.team)-p.contract.salary+terms.salary<=s.teams[p.team].wageLimit){p.contract={salary:terms.salary,end:s.year+terms.years,role:p.contract.role};continue;}}const t=p.team;p.previousTeam=t;p.team=-1;p.squad='free';p.contract=null;p.listing='Available';cancelFor(s,p.id);log(s,'Expiry',`${p.name} leaves ${s.teams[t].tag} as a free agent.`,[p.id]);}for(const t of s.teams){for(const r of ROLES)fillRole(s,t.id,r);const grant=160000+Math.round(t.reputation*1000);money(s,t.id,grant);if(t.id===s.team)w.grant=grant;}
 for(let i=0;i<20;i++){const p=createPlayer(s,ROLES[i%5],48+rng(s)*28);p.age=19+Math.floor(rng(s)*9);s.players.push(p);}stayManager(s);w.stage='open';w.day=0;ensureMarket(s);updateAIListings(s);generateIncoming(s);log(s,'Budget',`Board investment received: $${w.grant.toLocaleString()}. Six transfer rounds are open.`);return ok('Free agency is open. Expiring players have left and board funds are available.');}
function canCover(s,t,outgoing,incoming){for(const role of ROLES)if(!s.players.some(p=>p.team===t&&p.role===role&&!outgoing.includes(p.id))&&!incoming.some(id=>getPlayer(s,id)?.role===role))return false;return true;}
function tradePrice(s,p,buyer){const current=getPlayer(s,s.teams[buyer].lineup[p.role]);const improvement=overall(p)-(current?overall(current):50);return marketValue(s,p)*(p.listing==='Listed'?.85:1)*(improvement>0?1+Math.min(.25,improvement*.025):.9);}
export function evaluateTrade(s,deal){const {team,give,take,cash}=deal;if(!Number.isInteger(team)||team===s.team||!s.teams[team]||!Array.isArray(give)||!Array.isArray(take)||give.length>2||take.length>2||give.length+take.length===0||new Set([...give,...take]).size!==give.length+take.length||!Number.isInteger(cash)||Math.abs(cash)>1000000)return {valid:false,reason:'Choose up to two players per side and a valid cash amount.'};const gp=give.map(id=>getPlayer(s,id)),tp=take.map(id=>getPlayer(s,id));if(gp.some(p=>p?.team!==s.team)||tp.some(p=>p?.team!==team))return {valid:false,reason:'A player has moved clubs. Rebuild the proposal.'};if(gp.some(p=>!draftEligible(s,p,team))||tp.some(p=>!draftEligible(s,p,s.team)))return {valid:false,reason:'Special players can only join LCS or LCK clubs.'};if(tp.some(p=>p.listing==='Untouchable'))return {valid:false,reason:'The other club will not discuss its protected player.'};if(!canCover(s,s.team,give,take)||!canCover(s,team,take,give))return {valid:false,reason:'Both clubs need a player for every role after the deal.'};if(!tradeFits(s,s.team,give,take)||!tradeFits(s,team,take,give))return {valid:false,reason:'The deal must leave both clubs with at most 2 bench and 6 academy players.'};const userWages=committedPayroll(s)-gp.reduce((n,p)=>n+p.contract.salary,0)+tp.reduce((n,p)=>n+p.contract.salary,0),otherWages=payroll(s,team)+gp.reduce((n,p)=>n+p.contract.salary,0)-tp.reduce((n,p)=>n+p.contract.salary,0);if(userWages>s.teams[s.team].wageLimit||otherWages>s.teams[team].wageLimit)return {valid:false,reason:'The deal exceeds one club’s annual wage budget.'};if(cash>spendable(s)||-cash>cashFor(s,team))return {valid:false,reason:'One club cannot fund the cash portion.'};const sent=gp.reduce((n,p)=>n+tradePrice(s,p,team),0)+cash,requested=tp.reduce((n,p)=>n+marketValue(s,p)*(p.listing==='Listed'?.88:1.15),0),gap=round(requested-sent),accepted=gap<=0;return {valid:true,accepted,gap,counterCash:cash+Math.max(0,gap),userWages,otherWages,reason:accepted?'The club considers this a fair deal.':`They want $${Math.max(0,gap).toLocaleString()} more in value.`,sent:round(sent),requested:round(requested)};}
export function submitTrade(s,deal){if(!marketOpen(s))return no('Trades open in preseason, offseason, and before your sixth regular-season series. They close during playoffs and internationals.');if(s.phase==='regular'&&regularSeriesPlayed(s,deal.team)>=5)return no('That club has reached its sixth-series trade deadline.');const q=evaluateTrade(s,deal);if(!q.valid)return no(q.reason);const d={...deal,give:[...deal.give],take:[...deal.take],id:'t'+s.market.next++,status:q.accepted?'agreed':'counter',counterCash:q.counterCash,expires:s.market.clock+2,kind:'outgoing',message:q.reason};s.market.inbox.unshift(d);return ok(q.accepted?'Trade agreed in principle. Review and complete it in Offers.':'Counteroffer received. Review the revised cash in Offers.');}
export function completeTrade(s,id){const d=s.market.inbox.find(x=>x.id===id);if(!marketOpen(s)||!d||!['agreed','counter','incoming'].includes(d.status))return no('This offer is no longer available.');if(s.market.clock>d.expires){d.status='expired';return no('The proposal expired.');}if(s.phase==='regular'&&regularSeriesPlayed(s,d.team)>=5)return no('That club’s regular-season trade deadline has passed.');const deal={...d,cash:d.status==='counter'?d.counterCash:d.cash},q=evaluateTrade(s,deal);if(!q.valid)return no(q.reason);if(!q.accepted)return no('Values have changed. Submit a new proposal.');const names=ids=>ids.map(id=>getPlayer(s,id).name).join(' + ')||'cash';const text=`${s.teams[s.team].tag} ↔ ${s.teams[d.team].tag}: ${names(d.give)} for ${names(d.take)}${deal.cash?` ($${Math.abs(deal.cash).toLocaleString()} ${deal.cash>0?'paid':'received'})`:''}.`;for(const [ids,t] of [[d.give,d.team],[d.take,s.team]])for(const id of ids){const p=getPlayer(s,id);p.academyService=0;p.previousTeam=p.team;p.team=t;p.listing='Available';p.contract.promise={played:0,eligible:0,checked:0};cancelFor(s,id);}
 money(s,s.team,-deal.cash);money(s,d.team,deal.cash);for(const t of [s.team,d.team])for(const r of ROLES)fillRole(s,t,r);d.status='completed';d.cash=deal.cash;log(s,'Trade',text,[...d.give,...d.take],deal.cash);for(const x of s.market.inbox)if(x.id!==id&&['incoming','agreed','counter'].includes(x.status)&&[...x.give,...x.take].some(p=>[...d.give,...d.take].includes(p)))x.status='superseded';return ok('Trade completed. Contracts transfer with the players; review your starting five.');}
export function rejectTrade(s,id){const d=s.market.inbox.find(x=>x.id===id);if(s.match||!d||!['incoming','counter','agreed'].includes(d.status))return no('Offer is no longer active.');d.status='declined';return ok('Proposal declined.');}
export function academyCompensation(s,p){return p.squad==='academy'&&!p.developmentPaid&&p.contract.role==='Prospect'&&(p.academyService||0)>=4?round(Math.min(8000,(p.academyService||0)*500+Math.max(0,overall(p)-p.initial)*500)):0;}
export function releaseCost(s,p){if(p.squad==='academy'&&p.contract.role==='Prospect')return -academyCompensation(s,p);return round(p.contract.salary*Math.max(1,p.contract.end-targetYear(s)+1)*.35);}
export function releasePlayer(s,id){const p=getPlayer(s,id);if(s.match||p?.team!==s.team)return no('Player cannot be released now.');if(!canCover(s,s.team,[id],[]))return no('Recruit a replacement for this role before releasing the player.');const cost=releaseCost(s,p);if(spendable(s)<cost)return no('Insufficient uncommitted funds for the settlement.');money(s,s.team,-cost);p.developmentPaid=true;p.academyService=0;p.previousTeam=p.team;p.team=-1;p.squad='free';p.contract=null;p.listing='Available';cancelFor(s,id);fillRole(s,s.team,p.role);log(s,'Release',`${p.name} released by ${s.teams[s.team].tag}; $${Math.abs(cost).toLocaleString()} ${cost<0?'development compensation received':'settlement paid'}.`,[id],cost);return ok(cost<0?'Academy player released. Development compensation received.':'Player released into free agency.');}
function updateAIListings(s){for(const t of s.teams.filter(t=>t.id!==s.team)){const ps=s.players.filter(p=>p.team===t.id);for(const p of ps){const starting=t.lineup[p.role]===p.id;const better=ps.some(x=>x.role===p.role&&overall(x)>overall(p)+2);p.listing=starting&&overall(p)>=85?'Untouchable':(!starting||better?'Listed':'Available');}}}
function generateIncoming(s){const candidates=s.players.filter(p=>p.team===s.team&&p.listing!=='Untouchable'&&!p.emergency).sort((a,b)=>(b.listing==='Listed')-(a.listing==='Listed'));let made=0;for(const p of candidates){if(made>=2)break;if(s.market.inbox.some(d=>['incoming','counter','agreed'].includes(d.status)&&d.give.includes(p.id)))continue;const clubs=s.teams.filter(t=>t.id!==s.team).sort((a,b)=>overall(getPlayer(s,a.lineup[p.role]))-overall(getPlayer(s,b.lineup[p.role])));for(const t of clubs){const other=getPlayer(s,t.lineup[p.role]);if(other.listing==='Untouchable')continue;const give=[p.id],take=canCover(s,s.team,give,[])?[]:[other.id];const base={team:t.id,give,take,cash:0},q=evaluateTrade(s,base);if(!q.valid)continue;const cash=-round(Math.max(0,(q.sent-q.requested)*.85));const deal={...base,cash};const check=evaluateTrade(s,deal);if(!check.valid||!check.accepted)continue;s.market.inbox.unshift({...deal,id:'t'+s.market.next++,kind:'incoming',status:'incoming',expires:s.market.clock+2,message:`${t.name} want ${p.name} to strengthen ${p.role}.`});made++;break;}}}
function aiRecruit(s){const protectedIds=new Set(s.market.offers.filter(pending).map(o=>o.player));for(const t of s.teams.filter(t=>t.id!==s.team)){if(rng(s)>.6)continue;const roles=ROLES.slice().sort((a,b)=>overall(getPlayer(s,t.lineup[a]))-overall(getPlayer(s,t.lineup[b])));const role=roles[0],current=getPlayer(s,t.lineup[role]);const youth=academy(s,t.id).filter(p=>p.role===role&&overall(p)>overall(current)+1).sort((a,b)=>overall(b)-overall(a))[0];if(youth&&squad(s,t.id).length<7){youth.squad='main';t.lineup[role]=youth.id;youth.contract.role='Starter';current.listing='Listed';log(s,'Promotion',`${t.tag} promote academy ${role} ${youth.name} to the starting five.`,[youth.id]);continue;}if(full(s,t.id))continue;const free=s.players.filter(p=>p.team<0&&!protectedIds.has(p.id)&&draftEligible(s,p,t.id)&&p.role===role&&overall(p)>overall(current)+1).sort((a,b)=>overall(b)-overall(a));const p=free.find(p=>{const a=askingTerms(s,p,t.id);return payroll(s,t.id)+a.salary<=t.wageLimit&&cashFor(s,t.id)>=a.bonus;});if(p){const ask=askingTerms(s,p,t.id);if(signContract(s,{...ask,role:'Starter',player:p.id,renewal:false},t.id)){t.lineup[role]=p.id;current.listing='Listed';}}}
 // One club-to-club cash transfer per round, with coverage and finance checks.
 const listed=s.players.filter(p=>p.team>=0&&p.team!==s.team&&p.listing==='Listed'&&!protectedIds.has(p.id));for(const p of listed){const seller=p.team;if(!canCover(s,seller,[p.id],[]))continue;const buyer=s.teams.find(t=>t.id!==s.team&&t.id!==seller&&draftEligible(s,p,t.id)&&!full(s,t.id)&&overall(getPlayer(s,t.lineup[p.role]))+3<overall(p)&&cashFor(s,t.id)>=marketValue(s,p)&&payroll(s,t.id)+p.contract.salary<=t.wageLimit);if(!buyer)continue;const price=marketValue(s,p);money(s,buyer.id,-price);money(s,seller,price);p.team=buyer.id;p.squad='main';p.listing='Available';buyer.lineup[p.role]=p.id;fillRole(s,seller,p.role);log(s,'Transfer',`${buyer.tag} buy ${p.name} from ${s.teams[seller].tag} for $${price.toLocaleString()}.`,[p.id],price);break;}
}
export function advanceWindow(s){const w=s.market.window;if(s.phase!=='offseason'||w?.stage!=='open'||s.match||s.clubEvent||s.celebration)return no('The transfer window is not ready to advance.');if(w.day>=w.total)return no('Deadline reached. Sign agreed deals, then close the window.');s.market.clock++;w.day++;decayConnections(s);for(const p of s.players.filter(p=>p.team>=0)){for(const k of SKILLS)p.skills[k]=clamp(p.skills[k]+(rng(s)-.40)*(p.squad==='academy'?.65:.35)*p.learning*(p.age>29?.3:1));p.fatigue=clamp(p.fatigue-3,0,100);}processOffers(s);for(const d of s.market.inbox)if(['incoming','counter','agreed'].includes(d.status)&&s.market.clock>d.expires)d.status='expired';aiRecruit(s);updateAIListings(s);if(w.day<w.total)generateIncoming(s);for(const id of s.scouting){const p=getPlayer(s,id);if(p)p.scout=Math.min(2,p.scout+1);}s.scouting=[];return ok(w.day===w.total?'Deadline day. Complete agreed deals before closing the window.':`Transfer round ${w.day} complete. Agents and clubs have responded.`);}
export function closeWindow(s){const w=s.market.window;if(s.phase!=='offseason'||w?.stage!=='open'||w.day<w.total)return no('Complete all six transfer rounds first.');for(const d of s.market.inbox)if(['agreed','counter','incoming'].includes(d.status))d.status='declined';for(const o of s.market.offers.filter(pending)){o.status='withdrawn';o.message='Declined when the transfer window closed.';}w.stage='closed';log(s,'Deadline',`Transfer deadline: ${s.teams[s.team].tag} close the window with ${s.players.filter(p=>p.team===s.team).length} players.`);return ok('Window closed. Choose a preseason camp and start the academy draft.');}
export const CAMPS={Integration:{cost:10000,text:'Build familiarity across the starting five. +10 to each pair.'},Bootcamp:{cost:18000,text:'Every starter gains +0.8 in all four skills. +10 fatigue.'},Recovery:{cost:0,text:'Every player loses 30 fatigue and gains 3 Form.'}};
export function chooseCamp(s,name){const w=s.market.window,c=CAMPS[name];if(s.phase!=='offseason'||w?.stage!=='closed'||!c)return no('Choose a camp after closing the transfer window.');if(w.camp)return no('Your preseason camp is already complete.');if(spendable(s)<c.cost)return no('Insufficient funds for this camp.');money(s,s.team,-c.cost);const ps=starters(s);if(name==='Integration'){for(let i=0;i<5;i++)for(let j=i+1;j<5;j++){const key=[ps[i].id,ps[j].id].sort().join('|');s.bonds[key]=clamp((s.bonds[key]||0)+10,0,100);}}else if(name==='Bootcamp'){for(const p of ps){for(const k of SKILLS)p.skills[k]=clamp(p.skills[k]+.8);p.fatigue=clamp(p.fatigue+10,0,100);}}else for(const p of s.players.filter(p=>p.team===s.team)){p.fatigue=clamp(p.fatigue-30,0,100);p.form=clamp(p.form+3,50,100);}w.camp=name;offseasonReport(s);log(s,'Camp',`${name} camp completed before ${w.year}.`,ps.map(p=>p.id),c.cost);return ok('Preseason camp complete. Your roster is ready for the new year.');}
export function marketMatchday(s,teams){s.market.clock++;processOffers(s);for(const t of teams){for(const p of s.players.filter(p=>p.team===t&&p.squad==='main'&&p.contract?.promise)){const pr=p.contract.promise;pr.eligible++;if(s.teams[t].lineup[p.role]===p.id)pr.played++;if(pr.eligible-pr.checked<4)continue;pr.checked=pr.eligible;const share=pr.played/pr.eligible,min=p.contract.role==='Starter'?.6:p.contract.role==='Rotation'?.25:0;if(share<min){p.trust=clamp(p.trust-8,0,100);p.form=clamp(p.form-3,50,100);if(t===s.team)log(s,'Promise',`${p.name} is unhappy with playing time: ${Math.round(share*100)}% starts against a ${p.contract.role.toLowerCase()} promise. −3 Form.`,[p.id]);}else p.trust=clamp(p.trust+2,0,100);}}}
export function recruitmentFit(s,p){const current=getPlayer(s,s.teams[s.team].lineup[p.role]);return {current,delta:overall(p)-overall(current),need:overall(p)>overall(current)+2?'Upgrade':p.age<22?'Development':'Depth'};}
export function validateMarket(s,fail){const m=s.market;if(!m||!Number.isInteger(m.clock)||m.clock<0||!Number.isInteger(m.next)||!['offers','inbox','ledger','shortlist'].every(k=>Array.isArray(m[k])))fail();if(m.window&&(!['review','open','closed'].includes(m.window.stage)||!Number.isInteger(m.window.day)||m.window.day<0||m.window.day>6||m.window.total!==6||!Number.isInteger(m.window.year)||m.window.camp!==null&&!Object.hasOwn(CAMPS,m.window.camp)))fail();for(const o of m.offers){if(!getPlayer(s,o.player)||!validTerms(o)||!['waiting','counter','agreed','signed','withdrawn','replaced','expired','unavailable','lost','rejected'].includes(o.status)||!Number.isInteger(o.expires)||o.status==='counter'&&!validTerms(o.counter)||!Array.isArray(o.rivals)||o.rivals.some(r=>!s.teams[r.team]||!validTerms(r)))fail();}for(const d of m.inbox)if(!s.teams[d.team]||!Array.isArray(d.give)||!Array.isArray(d.take)||[...d.give,...d.take].some(id=>!getPlayer(s,id))||!Number.isFinite(d.cash)||!Number.isInteger(d.expires))fail();for(const p of s.players)if(!CONTRACT_YEARS.includes(p.preferredYears)||!PRIORITIES.includes(p.preference)||!['LCS','LCK','LPL','LEC'].includes(p.homeRegion)||!Number.isFinite(p.trust)||p.trust<0||p.trust>100||!['Available','Listed','Untouchable'].includes(p.listing))fail();for(const t of s.teams)if(!Number.isFinite(t.funds)||t.funds<0||!Number.isFinite(t.wageLimit)||t.wageLimit<0)fail();}

function offseasonReport(s){const w=s.market.window;const rows=s.players.filter(p=>p.team===s.team).map(p=>{const b=w.developmentBaseline?.[p.id];return {id:p.id,name:p.name,role:p.role,group:p.squad==='academy'?'Academy':s.teams[s.team].lineup[p.role]===p.id?'Starters':'Bench',change:Object.fromEntries(SKILLS.map(k=>[k,+(p.skills[k]-(b?.skills[k]??p.skills[k])).toFixed(2)])),overall:overall(p),form:Math.round(p.form),note:!b||b.team!==s.team?'Joined during offseason':'Retained',formChange:Math.round(p.form-(b?.form??p.form))};});s.reports.push({year:s.year+1,type:'offseason',camp:w.camp,rows});s.reportBaseline=Object.fromEntries(s.players.filter(p=>p.team===s.team).map(p=>[p.id,{...p.skills}]));s.reportStart=s.step;s.news.unshift('Offseason development report ready: main roster and academy progress, including preseason camp.');}
